  private def encodeJson(value: JsonValue, pretty: Boolean, indent: Int, level: Int): String = value match {
    case null => "null"
    case s: String => "\"" + escapeJson(s) + "\""
    case b: Boolean => if (b) "true" else "false"
    case bd: BigDecimal => bd.toString
    case bd: java.math.BigDecimal => BigDecimal(bd).toString
    case n: Number => n.toString
    case seq: Seq[_] =>
      val items = seq.map(v => encodeJson(v, pretty, indent, level + 1))
      renderArray(items, pretty, indent, level)
    case arr: Array[_] =>
      val items = arr.toSeq.map(v => encodeJson(v, pretty, indent, level + 1))
      renderArray(items, pretty, indent, level)
    case m: Map[_, _] =>
      val items = m.toSeq.map { case (k, v) =>
        val key = k.toString
        val encoded = encodeJson(v, pretty, indent, level + 1)
