  private def renderArray(items: Seq[String], pretty: Boolean, indent: Int, level: Int): String = {
    if (items.isEmpty) return "[]"
    if (!pretty) return items.mkString("[", ",", "]")

    val pad = " " * (indent * (level + 1))
    val closePad = " " * (indent * level)
    items.mkString("[\n" + pad, ",\n" + pad, s"\n$closePad]")
  }

  private def renderObject(items: Seq[String], pretty: Boolean, indent: Int, level: Int): String = {
    if (items.isEmpty) return "{}"
    if (!pretty) return items.mkString("{", ",", "}")

    val pad = " " * (indent * (level + 1))
    val closePad = " " * (indent * level)
    items.mkString("{\n" + pad, ",\n" + pad, s"\n$closePad}")
  }

  private def renderKeyValue(key: String, encodedValue: String, pretty: Boolean): String = {
    val k = "\"" + escapeJson(key) + "\""
    if (pretty) s"$k: $encodedValue" else s"$k:$encodedValue"
  }

  private def escapeJson(s: String): String =
