      case '\f' => "\\f"
      case '\n' => "\\n"
      case '\r' => "\\r"
      case '\t' => "\\t"
      case c if c.isControl => f"\\u${c.toInt}%04x"
      case c => c.toString
    }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    val stripped =
      if (stripPunctuation) stripEdgePunctuation(word)
      else word

    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) return None

    val limited = maxLength match {
      case Some(max) if normalized.length > max => normalized.take(max)
      case _ => normalized
    }

    if (limited.isEmpty) None else Some(limited)
  }

  private def stripEdgePunctuation(word: String): String = {
    val start = word.dropWhile(punctuation.contains)
    start.reverse.dropWhile(punctuation.contains).reverse
  }

  def tokenize(text: String): Vector[Token] = {
    val words = text.split("\\s+")
    val tokens = mutable.ArrayBuffer.empty[Token]

    words.zipWithIndex.foreach { case (word, idx) =>
      processToken(word).foreach { processed =>
        tokens += Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }

    tokens.toVector
  }

  def tokenizeToStrings(text: String): Vector[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): Vector[(String, Int, Int)] = {
    val result = mutable.ArrayBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = if (start >= 0) start + word.length else currentPos

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toVector
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] {
  private val normalizers = mutable.ArrayBuffer.empty[String => String]
  private val validators = mutable.ArrayBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(kvs: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= kvs
    this
  }

  def build(): T => Token = {
    val normalizersSnapshot = normalizers.toVector
    val validatorsSnapshot = validators.toVector
    val metadataSnapshot = metadata.toMap

    (value: T) => {
      validatorsSnapshot.foreach { validator =>
        if (!validator(value))
          throw new IllegalArgumentException(s"Validation failed for $value")
      }

      val normalized = normalizersSnapshot.foldLeft(value.toString) { (acc, norm) =>
        norm(acc)
      }

      Token(normalized, TokenType.STRING, metadataSnapshot)
    }
  }
}
